"""Returns the URL to the PBF for the region / subregion.

    Parameters
    ----------------------
    region : str
    subregion : str

    Returns
    ----------------------
    pbf_url : str
    """
def get_pbf_url(region: Any, subregion: Any) -> object {
    base_url = 'https://download.geofabrik.de';
    if (subregion is None) {
        pbf_url = f'{base_url}/{region}-latest.osm.pbf';
    } else {
        pbf_url = f'{base_url}/{region}/{subregion}-latest.osm.pbf';
    }
    return pbf_url;
}

"""Build network URI for NSX Proxy API.

    It replaces '/api/edgeGatway/' or '/api/admin/edgeGatway/' with
    /network/EDGE_ENDPOINT and return the newly formed network URI.

    param: str gateway_href: gateway URL. for ex:
    https://x.x.x.x/api/admin/edgeGateway/uuid

    return network href
    rtype: str
    """
def build_network_url_from_gateway_url(gateway_href: Any) -> object {
    _NETWORK_URL = '/network/edges/';
    _GATEWAY_API_URL = '/api/edgeGateway/';
    _GATEWAY_ADMIN_API_URL = '/api/admin/edgeGateway/';
    network_url = gateway_href;
    if (
        (gateway_href.find(_GATEWAY_API_URL) > 0)
        or (gateway_href.find(_GATEWAY_ADMIN_API_URL) > 0)
    ) {
        network_url = network_url.replace(_GATEWAY_API_URL, _NETWORK_URL);
        return network_url.replace(_GATEWAY_ADMIN_API_URL, _NETWORK_URL);
    }
    return None;
}

"""Insertion Sort
    Complexity: O(n^2)
    """
def insertion_sort(arr: Any, simulation: Any = False) -> object {
    for i in range(len(arr)) {
        cursor = arr[i];
        pos = i;
        while ((pos > 0) and (arr[(pos - 1)] > cursor)) {
            arr[pos] = arr[(pos - 1)];
            pos = pos - 1;
        }
        arr[pos] = cursor;
    }
    return arr;
}
